<?php
require_once '../../config/auth.php'; require_once '../../config/database.php'; requireRole('admin');
$years=$pdo->query('SELECT id,tahun_ajaran FROM academic_years ORDER BY tanggal_mulai DESC')->fetchAll(PDO::FETCH_ASSOC); $yearId=(int)($_GET['academic_year_id']??0);
$sql="SELECT co.*,s.nama_lengkap,c.nama_kelas,c.jurusan,ay.tahun_ajaran FROM class_officers co INNER JOIN students s ON s.id=co.student_id INNER JOIN classes c ON c.id=co.class_id INNER JOIN academic_years ay ON ay.id=co.academic_year_id WHERE co.status <> 'aktif'";$params=[];if($yearId){$sql.=' AND co.academic_year_id=?';$params[]=$yearId;}$sql.=' ORDER BY ay.tanggal_mulai DESC,co.tanggal_selesai DESC,s.nama_lengkap';$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Riwayat Bendahara Kelas';require_once '../../includes/header.php';require_once '../../includes/sidebar.php'; ?>
<main class="main-content"><?php require_once '../../includes/navbar.php'; ?><section class="dashboard-container"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2>Riwayat Bendahara Kelas</h2><p class="text-muted">Arsip penugasan bendahara per tahun ajaran.</p></div><a class="btn btn-primary" href="index.php">Data Bendahara</a></div><form method="get" class="mb-3"><select class="form-select" style="max-width:280px" name="academic_year_id" onchange="this.form.submit()"><option value="">Semua tahun ajaran</option><?php foreach($years as $year): ?><option value="<?= (int)$year['id'] ?>" <?= $yearId===(int)$year['id']?'selected':'' ?>><?= htmlspecialchars($year['tahun_ajaran']) ?></option><?php endforeach ?></select></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Siswa</th><th>Kelas</th><th>Tahun Ajaran</th><th>Mulai</th><th>Selesai</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= htmlspecialchars($row['nama_lengkap']) ?></strong></td><td><?= htmlspecialchars($row['nama_kelas']) ?></td><td><?= htmlspecialchars($row['tahun_ajaran']) ?></td><td><?= htmlspecialchars($row['tanggal_mulai']) ?></td><td><?= htmlspecialchars($row['tanggal_selesai']?:'-') ?></td><td><?= htmlspecialchars(ucfirst($row['status'])) ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada riwayat bendahara.</td></tr><?php endif ?></tbody></table></div></div></section></main><?php require_once '../../includes/footer.php'; ?>
